        ("pub(crate) fn hold_point(cx: &ToolContext, h: &Hit, p: Point) -> Point {", "pub(crate) fn hold_point(cx: &ToolContext, h: &Hit, p: Point) -> Point {\n    if (cx.selection.contains(h.leaf) || h.ancestry.iter().any(|id| cx.selection.contains(*id)))\n        && let Some(q) = crate::guides::grab_selection_crossing(cx, p, cx.tol(HOVER_REACH))\n    {\n        return q;\n    }", 1),
        ("    fn press_nothing(&mut self, cx: &ToolContext, p: Point, grab: Point, m: Mods) {", "    fn press_nothing(&mut self, cx: &ToolContext, p: Point, grab: Point, m: Mods) {\n        if !m.shift && !m.cmd && let Some(center) = leo_selection_center(cx, p) {\n            self.state = State::Moving { start: p, press: p, hold: center, began: false, deselect: None, key: None, exclude: None };\n            return;\n        }", 1),
        ("pub(crate) fn hit_center(cx:", "/// A selected unfilled object can be dragged from its geometric centre.\npub(crate) fn leo_selection_center(cx: &ToolContext, p: Point) -> Option<Point> {\n    if !cx.leo_snapping || !cx.smart_guides || cx.snap_to_grid || !cx.selection.anchors.is_empty() || !cx.selection.segments.is_empty() {\n        return None;\n    }\n    let [id] = cx.selection.objects.as_slice() else { return None };\n    let editable = cx.doc.editable();\n    if !editable(*id) || !crate::direct::in_scope(cx.doc, cx.isolation, *id) { return None; }\n    let center = cx.doc.node(*id)?.geometric_bounds_with(&cx.doc.symbol_boxes())?.center();\n    (center.distance(p) <= cx.tol(HOVER_REACH)).then_some(center)\n}\n\npub(crate) fn hit_center(cx:", 1),
